'use strict';
const setupSteps=['Projeto','Diretora','Sprint','Equipe','Prompts e prazo','Entrega e avaliação'];
function setupValid(s){const c=s.setup;return c===undefined||c&&Number.isInteger(c.step)&&c.step>=0&&c.step<6&&typeof c.project==='string'&&(!c.project||s.projects.some(p=>p.id===c.project))&&typeof c.task==='string'&&(!c.task||(s.tasks||[]).some(t=>t.id===c.task))}
function setupOf(){const s=studio();if(!s.setup)s.setup={step:0,project:activeProjects()[0]?.id||'',task:''};return s.setup}
function setupTask(){const c=setupOf();return studio().tasks.find(t=>t.id===c.task&&t.project===c.project)||studio().tasks.find(t=>t.project===c.project)}
function setupReady(step){const c=setupOf(),pr=project(c.project),t=setupTask();if(step===0)return !!pr&&!pr.archived;if(step===1)return !!pr?.directorId&&person(pr.directorId)?.status==='Aprovado'&&personOnProject(person(pr.directorId),pr.id);if(step===2)return !!t;if(step===3)return !!t&&!!t.plan.trim();if(step===4)return !!t?.execution&&t.execution.handoffs.length===t.creators.length&&executionValid(t);return !!t&&t.status==='Entregue'&&evalsComplete(t)}
function setupPage(){
 const c=setupOf(),pr=project(c.project),t=setupTask(),lead=person(pr?.directorId);
 const descriptions=['Escolha a marca que vamos organizar agora.','Ajuste o perfil, aprove a contratação e defina quem responde por este projeto.','Escreva o que você quer que a diretora faça e quanto tempo ela tem.','Registre como a diretora divide a entrega. Ela pode trabalhar sozinha ou com até três criadores.','Revise os prompts e distribua o tempo, incluindo a revisão final.','Leve o briefing para execução, registre o material e avalie cada participante.'];
 let body='';
 if(c.step===0)body=`<label class="field"><span>Qual projeto vamos configurar?</span><select id="setup-project"><option value="">Escolha um projeto</option>${activeProjects().map(p=>`<option value="${esc(p.id)}" ${c.project===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label>${pr?`<p class="long-copy">${esc(pr.description)}</p><button class="btn" data-studio="project" data-id="${esc(pr.id)}">Ajustar contexto do projeto</button>`:''}<button class="btn" data-studio="new-project">${ico('plus')}Criar outro projeto</button>`;
 if(c.step===1)body=`${lead?`<div class="lead-profile"><img src="${personImage(lead)}" alt="Perfil fictício de ${esc(lead.name)}"><div><span class="eyebrow">DIRETORA DESTE PROJETO</span><h3>${esc(lead.name)}</h3><p>${esc(lead.status)} · capacidade ${lead.capacity||1}</p></div></div>`:'<p class="form-context">Escolha um perfil e ajuste personalidade, habilidades, autonomia e capacidade. A aprovação da contratação fica na ficha.</p>'}<div class="setup-profiles">${studio().people.filter(p=>p.kind!=='advisor'&&(/diret/i.test(p.role)||p.id===pr?.directorId)).map(p=>`<button class="setup-profile" data-studio="person" data-id="${esc(p.id)}"><img src="${personImage(p)}" alt=""><span><strong>${esc(p.name)}</strong><small>${esc(p.role)} · ${esc(p.status)}</small></span>${ico('pen')}</button>`).join('')}</div><div class="actions"><button class="btn" data-studio="new-person">Criar minha diretora</button>${pr?`<button class="btn primary" data-direction="manage" data-id="${esc(pr.id)}">Definir direção do projeto ${ico('arrow')}</button>`:''}</div>`;
 if(c.step===2)body=`<div class="setup-example"><span class="eyebrow">O QUE ESCREVER</span><h3>“Quero que você…”</h3><p>Exemplo: criar uma campanha para gerar pedidos de atendimento. Entregar três anúncios e uma proposta de página em 30 minutos.</p><p><strong>Objetivo e contexto</strong> recebe sua orientação. <strong>Material que você quer receber</strong> define a entrega.</p></div><button class="btn primary" data-setup="new-task">Escrever o briefing da sprint ${ico('pen')}</button>${t?`<label class="field"><span>Sprint em configuração</span><select id="setup-task">${studio().tasks.filter(x=>x.project===c.project).map(x=>`<option value="${esc(x.id)}" ${t.id===x.id?'selected':''}>${esc(x.title)}</option>`).join('')}</select></label><p class="long-copy">${esc(t.brief)}</p><button class="btn" data-agency="edit-task" data-id="${esc(t.id)}">Ajustar este briefing</button>`:''}`;
 if(c.step===3)body=t?`<h3>${esc(t.title)}</h3><p class="long-copy">${esc(t.plan||'A diretora ainda precisa definir o plano desta sprint.')}</p><p>${t.creators.length} criador(es) · ${esc(person(t.director).name)} na direção</p><button class="btn primary" data-agency="task-plan" data-id="${esc(t.id)}">Abrir plano da diretora ${ico('arrow')}</button>`:'<p>Volte à etapa Sprint para criar o briefing.</p>';
 if(c.step===4)body=t?`<div class="deadline-contract"><span class="eyebrow">UM PRAZO PARA TODA A EQUIPE</span><h3>${durationLabel(t.minutes)}</h3><p>Os repasses e a revisão precisam caber neste tempo.</p>${t.execution?.deadlineAt?`<small>Limite registrado: ${esc(dateLabel(t.execution.deadlineAt))}</small>`:''}</div><button class="btn primary" data-quality="plan" data-id="${esc(t.id)}">Revisar prompts e repasses ${ico('arrow')}</button><p class="small muted">O rascunho considera o briefing, a marca, o perfil e o feedback. A diretora personaliza cada rodada.</p>`:'<p>Crie uma sprint para configurar os repasses.</p>';
 if(c.step===5)body=t?`<div class="setup-example"><h3>${esc(t.title)}</h3><p>O briefing está preparado para levar à conversa. Nenhum agente é iniciado automaticamente pelo site.</p><button class="btn primary" data-agency="export-task" data-id="${esc(t.id)}">Levar ao ChatGPT ${ico('download')}</button></div><div class="actions"><button class="btn" data-agency="task-result" data-id="${esc(t.id)}">Registrar material</button><button class="btn" data-quality="eval" data-id="${esc(t.id)}">Avaliar a entrega</button><button class="btn" data-agency="task" data-id="${esc(t.id)}">Ver prazo e todos os registros</button></div><p class="form-context">${setupReady(5)?'Entrega e avaliações registradas. Você pode começar outra sprint.':'A conclusão exige material real e avaliações aprovadas. Use parcial ou revisar quando houver pendências.'}</p>`:'<p>Crie uma sprint para preparar sua execução.</p>';
 return `${heading('Vamos configurar juntos.','Uma decisão de cada vez. Você pode voltar e ajustar qualquer etapa.')}<nav class="setup-steps" aria-label="Etapas da configuração">${setupSteps.map((label,i)=>`<button data-setup="step" data-step="${i}" class="${i===c.step?'current':''}" ${i===c.step?'aria-current="step"':''}><b>${String(i+1).padStart(2,'0')}</b><span>${label}</span>${setupReady(i)?'<small>✓</small>':''}</button>`).join('')}</nav><section class="setup-panel"><div class="section-heading"><div><span class="eyebrow">ETAPA ${c.step+1} DE 6${pr?' · '+esc(pr.name):''}</span><h2>${setupSteps[c.step]}</h2></div><span class="chip">${setupReady(c.step)?'Configurado':'A configurar'}</span></div><p class="setup-description">${descriptions[c.step]}</p>${body}<div class="setup-footer"><button class="btn" data-setup="back" ${c.step===0?'disabled':''}>Voltar</button>${c.step<5?`<button class="btn primary" data-setup="next">Continuar ${ico('arrow')}</button>`:'<button class="btn primary" data-setup="another">Preparar outra sprint</button>'}</div></section><p class="small muted">Seu ponto de parada fica salvo neste navegador. O advisor Nizan pode ser chamado pelo projeto ou pela sala de reunião.</p>`;
}
function setupGo(step){const c=setupOf();if(step>c.step){for(let i=c.step;i<step;i++)if(!setupReady(i)){toast('Conclua a etapa '+setupSteps[i]+' antes de continuar.');return false}}c.step=step;persist('Avançou na configuração: '+setupSteps[step]);render();return true}
document.addEventListener('click',e=>{const b=e.target.closest('[data-setup]');if(!b)return;const c=setupOf(),a=b.dataset.setup;if(a==='next')setupGo(Math.min(5,c.step+1));if(a==='back')setupGo(Math.max(0,c.step-1));if(a==='step')setupGo(Number(b.dataset.step));if(a==='new-task'){c.task='';taskForm(undefined,c.project)}if(a==='another'){c.task='';c.step=2;persist('Preparou outra sprint');taskForm(undefined,c.project);render()}});
document.addEventListener('change',e=>{if(e.target.id==='setup-project'){const c=setupOf();c.project=e.target.value;c.task='';c.step=0;persist('Escolheu projeto na configuração');render()}if(e.target.id==='setup-task'){setupOf().task=e.target.value;persist('Escolheu sprint na configuração');render()}});
